const RIG_MAP = {
  'dual crank anchor': 2,
  'triad scissor arm': 3,
  'five tier lattice': 5,
  'seven bar pantograph': 7,
  'nine node spider': 9,
  'twelve bar web': 12
};

const TEMPO_MAP = {
  'deliberate bronze crawl': { base: 0.015, slip: 0 },
  'steady clockwork hum': { base: 0.03, slip: 0 },
  'syncopated cam pulse': { base: 0.05, slip: 1 },
  'clutch slip surge': { base: 0.04, slip: 2 },
  'frantic flywheel blur': { base: 0.15, slip: 0 },
  'whiplash torque cycle': { base: 0.2, slip: 3 }
};

const PROP_MAP = {
  'balanced golden fold': [0.618, 0.618],
  'elongated needle reach': [0.85, 0.45],
  'tiered nesting loop': [0.55, 0.85],
  'asymmetric canted reach': [0.95, 0.35],
  'fractured wide throw': [1.1, 0.5],
  'resonant orbit spread': [0.75, 0.75]
};

const ANCHOR_MAP = {
  'lone end stylus': 1,
  'opposed dual nibs': 2,
  'outer triad pins': 3,
  'alternating joint tips': -1,
  'all articulating pivots': 0,
  'total skeleton bath': -2
};

const INK_MAP = {
  'ghostly hairline drafting': { c: [200, 220, 255], w: 2, fade: 2 },
  'phosphor vapor streak': { c: [100, 255, 150], w: 2.5, fade: 3 },
  'molten amber ribbon': { c: [255, 150, 50], w: 3, fade: 2 },
  'electric cobalt flare': { c: [50, 150, 255], w: 3.5, fade: 4 },
  'saturated laser scar': { c: [255, 50, 100], w: 4, fade: 3 },
  'hyperdense incandescent wake': { c: [255, 255, 255], w: 5, fade: 1 }
};

let pg;
let time = 0;
let prevPositions = [];
let cx = 400, cy = 400;

p.setup = function() {
  p.createCanvas(800, 800);
  pg = p.createGraphics(800, 800);
  pg.background(12, 14, 18);
};

p.draw = function() {
  const rigKey = p.getSynthVar('linkage_rig') || 'dual crank anchor';
  const tempoKey = p.getSynthVar('crank_tempo') || 'deliberate bronze crawl';
  const propKey = p.getSynthVar('joint_proportions') || 'balanced golden fold';
  const anchorKey = p.getSynthVar('tracer_anchors') || 'lone end stylus';
  const inkKey = p.getSynthVar('ink_viscosity') || 'ghostly hairline drafting';

  const tiers = RIG_MAP[rigKey];
  const tempo = TEMPO_MAP[tempoKey];
  const props = PROP_MAP[propKey];
  const anchor = ANCHOR_MAP[anchorKey];
  const ink = INK_MAP[inkKey];

  // Crank Kinematics - uncoupled from time to prevent feedback lock
  let currentSpeed = tempo.base;
  if (tempo.slip > 0) {
    let phase = p.frameCount * 0.05;
    let slipFactor = p.sin(phase * tempo.slip * 1.5);
    if (tempo.slip === 2 && slipFactor > 0.85) {
       currentSpeed *= 6.0; // explosive starburst snap
    } else if (tempo.slip === 3) {
       currentSpeed *= p.cos(phase * 4.0); // backwards reverse
    } else {
       currentSpeed *= (1.0 + slipFactor * 0.5);
    }
  }

  // Motion constraint
  if (Math.abs(currentSpeed) < 0.02) {
    currentSpeed = (currentSpeed >= 0 ? 0.02 : -0.02);
  }
  time += currentSpeed;

  // Fade Buffer
  pg.blendMode(p.BLEND);
  pg.noStroke();
  pg.fill(12, 14, 18, ink.fade);
  pg.rect(0, 0, 800, 800);

  p.background(12, 14, 18);

  let baseLen = 180; 
  let nodes = [];

  for (let arm = 0; arm < 6; arm++) {
    let armNodes = [{x: cx, y: cy}];
    let currentAngle = (p.TWO_PI / 6) * arm;

    for (let i = 1; i <= tiers; i++) {
      let prev = armNodes[i-1];
      let len = baseLen * (i === 1 ? 1 : Math.pow(props[(i%2)], i-1)) * 1.2;
      len = p.constrain(len, 15, 350); 

      let spin = currentAngle + (time * i * (i % 2 === 0 ? -1.5 : 1.2));
      let nx = prev.x + p.cos(spin) * len;
      let ny = prev.y + p.sin(spin) * len;
      armNodes.push({x: nx, y: ny});
    }
    nodes.push(armNodes);
  }

  // Buffer structure reset check
  if (!prevPositions.length || prevPositions.length !== 6 || prevPositions[0].length !== (tiers + 1)) {
    prevPositions = nodes.map(arm => arm.map(n => ({...n})));
  }

  // Batch Trace Drawing
  pg.stroke(ink.c[0], ink.c[1], ink.c[2]);
  pg.strokeWeight(ink.w);
  pg.beginShape(p.LINES);
  for (let arm = 0; arm < 6; arm++) {
    for (let i = 1; i <= tiers; i++) {
      let isTracer = false;
      if (anchor === 1 && i === tiers) isTracer = true;
      else if (anchor === 2 && i >= tiers - 1) isTracer = true;
      else if (anchor === 3 && i >= tiers - 2) isTracer = true;
      else if (anchor === -1 && i % 2 === 1) isTracer = true;
      else if (anchor === 0 || anchor === -2) isTracer = true;

      if (isTracer) {
        let curr = nodes[arm][i];
        let prev = prevPositions[arm][i];
        pg.vertex(prev.x, prev.y);
        pg.vertex(curr.x, curr.y);
      }
    }
  }
  pg.endShape();

  if (anchor === -2) {
    pg.strokeWeight(ink.w * 2.5);
    pg.beginShape(p.POINTS);
    for (let arm = 0; arm < 6; arm++) {
      for (let i = 1; i <= tiers; i++) {
        pg.vertex(nodes[arm][i].x, nodes[arm][i].y);
      }
    }
    pg.endShape();
  }

  prevPositions = nodes.map(arm => arm.map(n => ({...n})));

  p.image(pg, 0, 0);

  // Draft Geometry UI
  p.stroke(255, 75);
  p.strokeWeight(1.5);
  p.noFill();

  for (let arm = 0; arm < 6; arm++) {
    p.beginShape();
    for (let i = 0; i <= tiers; i++) {
      p.vertex(nodes[arm][i].x, nodes[arm][i].y);
    }
    p.endShape();

    // Draw joints
    p.stroke(255, 120);
    p.beginShape(p.POINTS);
    p.strokeWeight(4);
    for (let i = 0; i <= tiers; i++) {
      p.vertex(nodes[arm][i].x, nodes[arm][i].y);
    }
    p.endShape();
    p.strokeWeight(1.5);
    p.stroke(255, 75);

    // Web lattice constraints
    if (tiers >= 3) {
       p.beginShape(p.LINES);
       for (let i = 2; i <= tiers; i+=2) {
          let nextArm = (arm + 1) % 6;
          p.vertex(nodes[arm][i].x, nodes[arm][i].y);
          p.vertex(nodes[nextArm][i].x, nodes[nextArm][i].y);
       }
       p.endShape();
    }
  }
};
